package com.aistock.notification.alertmail;

import com.aistock.notification.alert.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;

@Tag("mysql") class AlertMailOutboxMysqlTest extends AlertMailDatabaseFixture {
 @Test void createsEligibleDecisionWithFixedVersionsAndExpiry(){preference(true,3);var d=capture(true,true);var row=repo.find(d.deliveryId());assertEquals("PENDING",row.state());assertEquals(3,row.preferenceRevision());assertEquals(7,row.accountRevision());assertEquals(clock.instant().plusSeconds(86400),row.expiresAt());assertEquals(1,count("inbox_message"));assertEquals(1,count("alert_mail_delivery"));}
 @Test void recordsWhyNewTriggerDoesNotRequestEmail(){preference(true,3);assertEquals("SYSTEM_DISABLED",capture(false,true).reasonCode());trigger=UUID.randomUUID();jdbc.update("update alert_trigger set trade_date='2026-10-08' where owner_id=?",owner.toString());preference(false,4);assertEquals("PREFERENCE_OFF",capture(true,true).reasonCode());trigger=UUID.randomUUID();jdbc.update("update alert_trigger set trade_date=date_sub(trade_date,interval 2 day) where owner_id=?",owner.toString());preference(true,5);assertEquals("EMAIL_UNVERIFIED",capture(true,false).reasonCode());assertNull(repo.claim(clock.instant(),Duration.ofSeconds(120)));}
 @Test void refusingOutboxInsertRollsBackTriggerAndInbox(){preference(true,1);String name="fail_mail_"+owner.toString().replace("-","");jdbc.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON alert_mail_delivery FOR EACH ROW BEGIN IF NEW.owner_id='"+owner+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture reject'; END IF; END");try{assertThrows(RuntimeException.class,()->capture(true,true));assertEquals(0,count("alert_trigger"));assertEquals(0,count("inbox_message"));}finally{jdbc.execute("DROP TRIGGER "+name);}}
 @Test void refusesCaptureOutsideTransactionAndNeverBackfillsOldMessages(){repo.locked(owner,()->{insertTrigger();return null;});assertThrows(IllegalStateException.class,()->new AlertMailOutbox(repo,true,Duration.ofHours(24)).capture(trigger,owner,rule,0,context(true),clock.instant()));assertNull(repo.claim(clock.instant(),Duration.ofSeconds(120)));assertEquals(0,count("alert_mail_delivery"));}
 @Test void duplicateTriggerCannotCreateTwoDeliveries(){preference(true,1);var first=capture(true,true);assertThrows(org.springframework.dao.DuplicateKeyException.class,()->repo.locked(owner,()->new AlertMailOutbox(repo,true,Duration.ofHours(24)).capture(trigger,owner,rule,0,context(true),clock.instant())));assertEquals(1,count("alert_mail_delivery"));assertNotNull(repo.find(first.deliveryId()));}
 @Test void concurrentClaimHasOneOwnerAndCheckingCanRecover()throws Exception{preference(true,1);var d=capture(true,true);var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<AlertMailRecords.Delivery>>of(()->repo.claim(clock.instant(),Duration.ofSeconds(120)),()->repo.claim(clock.instant(),Duration.ofSeconds(120))));int claims=0;for(var f:results)if(f.get()!=null)claims++;assertEquals(1,claims);}finally{pool.shutdownNow();}var old=repo.find(d.deliveryId());var recovered=repo.claim(clock.instant().plusSeconds(121),Duration.ofSeconds(120));assertNotNull(recovered);assertNotEquals(old.leaseToken(),recovered.leaseToken());assertEquals(0,recovered.attempts());}
 @Test void staleSendingIsUnknownAndNeverClaimedAgain(){preference(true,1);var d=capture(true,true);var lease=repo.claim(clock.instant(),Duration.ofSeconds(120));jdbc.update("update alert_mail_delivery set state='SENDING',attempts=1 where delivery_id=?",d.deliveryId().toString());assertNull(repo.claim(clock.instant().plusSeconds(121),Duration.ofSeconds(120)));assertEquals("UNKNOWN",repo.find(d.deliveryId()).state());assertNull(repo.claim(clock.instant().plusSeconds(500),Duration.ofSeconds(120)));assertEquals(1,count("inbox_message"));}
 @Test void expiredPendingNeverEntersSmtpPhase(){preference(true,1);var d=capture(true,true);assertNull(repo.claim(clock.instant().plusSeconds(86401),Duration.ofSeconds(120)));assertEquals("EXPIRED",repo.find(d.deliveryId()).state());}
}
